<?php
require __DIR__.'/../vendor/autoload.php';
$app=require __DIR__.'/../bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
if (!app()->environment('local')) throw new RuntimeException('Local test only');
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Cache;
use Illuminate\Http\Request;
use App\Services\LogRetentionService;
use App\Services\SystemLogService;
use App\Http\Controllers\V1\Admin\SystemController;
set_exception_handler(function($e){fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);});
config(['cache.default'=>'array']);
$checks=0;$assert=function($ok,$why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$reject=function($fn)use($assert){try{$fn();}catch(Illuminate\Validation\ValidationException $e){$assert(true,'validation rejected');return;}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$assert($e->getStatusCode()===422,'HTTP validation rejected');return;}throw new RuntimeException('Expected rejection');};
$now=time();DB::beginTransaction();
try {
    $retention=new LogRetentionService();$logs=new SystemLogService();$admin=new SystemController();
    DB::table('v2_risk_setting')->whereIn('key',array_keys(LogRetentionService::DEFAULTS))->delete();
    $assert($retention->settings()===LogRetentionService::DEFAULTS,'safe default policy');
    foreach ([['connection_log_retention_days'=>0],['login_log_retention_days'=>1],['risk_log_retention_days'=>29],['ddns_log_retention_days'=>366],['system_log_retention_days'=>'x']] as $bad) $reject(fn()=>$retention->save($bad));
    $retention->save(['connection_log_retention_days'=>45]);
    $assert($retention->settings()['system_log_retention_days']===30,'partial update preserves other categories');
    $r=(new App\Http\Controllers\V1\Risk\LogController())->getRiskSettings(Request::create('/'));
    $assert(json_decode($r->getContent(),true)['data']['connection_log_retention_days']===45,'shared connection policy');
    $retention->save(['connection_log_retention_days'=>30]);
    $login=DB::table('v2_login_log')->insertGetId(['email'=>'log-test@example.test','created_at'=>1]);
    $subscription=DB::table('v2_subscribe_log')->insertGetId(['user_id'=>999999,'created_at'=>1]);
    $connection=DB::table('v2_user_connection_log')->insertGetId(['user_id'=>999999,'connected_at'=>1]);
    // Exercise the real node request action: it must not delete expired history.
    $node=new App\Models\ServerV2box(['id'=>999999,'group_id'=>[]]);
    (new App\Services\Actions\NodeCommunication($node,'v2box'))->alive(Request::create('/','POST',[999999=>['8.8.8.8']]));
    $assert(DB::table('v2_user_connection_log')->where('id',$connection)->exists(),'node heartbeat never purges logs');
    $old=[];for($i=0;$i<4;$i++)$old[]=DB::table('v2_ddns_event')->insertGetId(['assignment_id'=>999999,'code'=>'healthy','created_at'=>1]);
    $boundary=DB::table('v2_ddns_event')->insertGetId(['assignment_id'=>999999,'code'=>'healthy','created_at'=>$now-30*86400]);
    $recent=DB::table('v2_ddns_event')->insertGetId(['assignment_id'=>999999,'code'=>'healthy','created_at'=>$now]);
    $counts=$retention->prune(2,1,$now);
    $assert(max($counts)<=2,'per-table batch size bounded');
    $assert(DB::table('v2_ddns_event')->whereIn('id',$old)->count()===2,'oldest bounded batch removed');
    $assert(DB::table('v2_ddns_event')->whereIn('id',[$boundary,$recent])->count()===2,'boundary and recent rows preserved');
    $assert(DB::table('v2_login_log')->where('id',$login)->exists() && DB::table('v2_subscribe_log')->where('id',$subscription)->exists(),'new categories not auto-enabled');
    $assert(!DB::table('v2_user_connection_log')->where('id',$connection)->exists(),'scheduler path removes old connection log');
    $risk=[];foreach(['pending','confirmed','false_positive','ignored','unreviewed','recent_review'] as $state){$review=$state==='unreviewed' ? [] : ['review'=>['state'=>$state==='recent_review' ? 'confirmed' : $state]];$risk[$state]=DB::table('v2_risk_rule_hit')->insertGetId(['scene'=>'test','rule_key'=>'test','payload'=>json_encode($review),'hit_at'=>1,'updated_at'=>$state==='recent_review' ? $now : 1]);}
    $statsBefore=[DB::table('v2_stat_user')->count(),DB::table('v2_stat_server')->count()];
    $retention->save(['login_log_retention_days'=>90,'subscribe_log_retention_days'=>90,'risk_log_retention_days'=>90]);
    $retention->prune(100,1,$now);
    $assert(!DB::table('v2_login_log')->where('id',$login)->exists() && !DB::table('v2_subscribe_log')->where('id',$subscription)->exists(),'configured old raw logs removed');
    foreach($risk as $state=>$id)$assert(DB::table('v2_risk_rule_hit')->where('id',$id)->exists()===in_array($state,['pending','unreviewed','recent_review']),'risk review retention: '.$state);
    $assert($statsBefore===[DB::table('v2_stat_user')->count(),DB::table('v2_stat_server')->count()],'log pruning leaves statistics untouched');
    // Mark pre-existing rows as indexed inside this rollback-only test to isolate backfill limits.
    DB::table('v2_log')->update(['metadata_indexed'=>true]);
    $uuid='120ab398-35a2-4bc2-b25f-7fa362114e02';
    $base=['title'=>'secret-legacy-message','level'=>'ERROR','host'=>'http://localhost','uri'=>'/path?token=secret-legacy-token','method'=>'POST','ip'=>'127.0.0.1','data'=>'secret-legacy-body','context'=>json_encode(['requestId'=>$uuid,'status'=>503,'durationMs'=>75,'password'=>'secret-legacy-password']),'created_at'=>$now,'updated_at'=>$now];
    $first=DB::table('v2_log')->insertGetId($base);
    $second=DB::table('v2_log')->insertGetId(array_replace($base,['context'=>'malformed-json']));
    $assert($logs->backfill(1)===1,'backfill is bounded');
    $assert(DB::table('v2_log')->find($first)->request_id===$uuid && !DB::table('v2_log')->find($second)->metadata_indexed,'old context indexed incrementally');
    $assert($logs->backfill(1)===1 && DB::table('v2_log')->find($second)->request_id===null,'malformed context safely consumed');
    $query=function($params)use($admin){$request=Request::create('/','GET',$params);app()->instance('request',$request);return json_decode($admin->getSystemLog($request)->getContent(),true);};
    $result=$query(['request_id'=>$uuid,'status'=>503,'level'=>'ERROR','from'=>$now-1,'to'=>$now+1]);
    $assert($result['total']===1 && $result['data'][0]['id']===$first,'combined exact indexed filters');
    $assert(!str_contains(json_encode($result),'secret-legacy') && !array_key_exists('context',$result['data'][0]),'legacy secrets excluded from response');
    $assert($query(['request_id'=>$uuid,'status'=>200])['total']===0,'status filter applied');
    $reject(fn()=>$query(['request_id'=>'anything%']));$reject(fn()=>$query(['from'=>100,'to'=>99]));$reject(fn()=>$query(['page_size'=>101]));
    $request=Request::create('/safe','POST',['token'=>'new-secret']);app()->instance('request',$request);
    $logger=new Monolog\Logger('test',[new App\Logging\MysqlLoggerHandler()]);
    $logger->info('Admin operation',['requestId'=>$uuid,'status'=>200,'durationMs'=>10]);
    $written=DB::table('v2_log')->orderByDesc('id')->first();
    $assert($written->request_id===$uuid && $written->http_status===200 && $written->metadata_indexed===1,'new log metadata indexed at write time');
    $assert(!str_contains(json_encode($written),'new-secret'),'new request secrets not captured');
    $assert($written->level==='INFO', 'Monolog 3 level stored as a string');
    $logger->error('unsafe exception text', ['requestId'=>$uuid, 'exception'=>new RuntimeException('private-exception-secret'), 'password'=>'private-password-secret']);
    $error=DB::table('v2_log')->orderByDesc('id')->first();
    $assert($error->level==='ERROR' && $error->title==='Application exception' && !str_contains(json_encode($error),'private-'), 'Monolog 3 exception context remains redacted');
    $explain=DB::select('EXPLAIN SELECT id FROM v2_log WHERE request_id = ? ORDER BY created_at DESC,id DESC',[$uuid]);
    $assert(str_contains($explain[0]->possible_keys ?? '', 'log_request_id_idx'),'request lookup has usable index');
    foreach(['v2_login_log','v2_subscribe_log'] as $table){$plan=DB::select('EXPLAIN SELECT id FROM '.$table.' WHERE created_at < ? ORDER BY created_at,id LIMIT 1000',[$now]);$assert(str_contains($plan[0]->possible_keys ?? '',$table.'_created_id_idx'),'cleanup has time index');}
    $kernel=app(Illuminate\Contracts\Http\Kernel::class);
    $path='/api/v1/'.config('v2board.secure_path',config('v2board.frontend_admin_path',hash('crc32b',config('app.key')))).'/system/logRetention';
    $assert($kernel->handle(Request::create($path,'POST',['system_log_retention_days'=>10],[],[],['HTTP_ACCEPT'=>'application/json']))->getStatusCode()===403,'retention settings admin-protected');
    $user=App\Models\User::create(['email'=>'logs-admin-'.bin2hex(random_bytes(5)).'@example.test','password'=>password_hash('test-only',PASSWORD_DEFAULT),'uuid'=>App\Utils\Helper::guid(true),'token'=>App\Utils\Helper::guid(),'is_admin'=>1]);
    $auth=(new App\Services\AuthService($user))->generateAuthData(Request::create('/'))['auth_data'];
    $response=$kernel->handle(Request::create($path,'POST',['system_log_retention_days'=>45],[],[],['HTTP_ACCEPT'=>'application/json','HTTP_AUTHORIZATION'=>$auth]));
    $assert($response->getStatusCode()===200 && json_decode($response->getContent(),true)['data']['system_log_retention_days']===45,'admin HTTP settings DI and save');
    $response=$kernel->handle(Request::create($path,'GET',[],[],[],['HTTP_ACCEPT'=>'application/json','HTTP_AUTHORIZATION'=>$auth]));
    $assert($response->getStatusCode()===200 && isset(json_decode($response->getContent(),true)['data']['settings']),'admin HTTP settings read');
    Cache::forget('LOG_RETENTION_LAST_RUN');
    $lock=Cache::lock('LOG_RETENTION_PRUNE_LOCK',300);$lock->get();
    $assert(Illuminate\Support\Facades\Artisan::call('logs:prune')===0 && Cache::get('LOG_RETENTION_LAST_RUN')===null,'concurrent cleanup skips safely');
    $lock->release();
    $assert(Illuminate\Support\Facades\Artisan::call('logs:prune')===0 && isset(Cache::get('LOG_RETENTION_LAST_RUN')['indexed']),'scheduled cleanup reports successful completion');
    echo "Log management: $checks checks passed\n";
} finally { DB::rollBack(); }
